local BatteringRamMaker = {}
local PRODUCTS = {
    simple_ram = { name = "Preprosti ovn", woodCost = 8, ironCost = 2, leatherCost = 2, time = 6, cost = 250, attack = 25, durability = 40, description = "Preprost oblegovalni ovn za lahtje zidove." },
    covered_ram = { name = "Pokriti ovn", woodCost = 10, ironCost = 3, leatherCost = 4, ropeCost = 2, time = 9, cost = 600, attack = 40, durability = 55, prestige = 2, description = "Pokriti ovn za zaščito pred streli." },
    iron_capped_ram = { name = "Železnoglavi ovn", woodCost = 12, ironCost = 5, leatherCost = 4, ropeCost = 2, time = 12, cost = 1300, attack = 60, durability = 75, prestige = 5, happiness = 1, description = "Ovn z železno konico za močne zidove." },
    steel_capped_ram = { name = "Jeklenoglavi ovn", woodCost = 14, ironCost = 5, steelCost = 2, leatherCost = 5, ropeCost = 3, time = 16, cost = 2600, attack = 85, durability = 95, prestige = 10, happiness = 2, description = "Ovn z jekleno konico za ojačana vrata." },
    silver_adorned_ram = { name = "Srebrno okrašen ovn", woodCost = 14, ironCost = 5, steelCost = 3, silverCost = 2, leatherCost = 5, ropeCost = 3, time = 19, cost = 4800, attack = 110, durability = 115, prestige = 18, happiness = 4, description = "Ovn s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_ram = { name = "Kraljevski veliki ovn", woodCost = 22, ironCost = 8, steelCost = 5, goldCost = 3, silverCost = 2, leatherCost = 7, ropeCost = 5, jewelCost = 1, time = 26, cost = 11000, attack = 170, durability = 170, prestige = 55, happiness = 11, description = "Veliki kraljevski oblegovalni ovn z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Ovnaška delavnica", cost = { gold = 450, wood = 250, stone = 200 }, upkeep = 11, qualityBonus = 5 },
    siege_yard = { name = "Oblegovalno dvorišče", cost = { gold = 1400, wood = 400, stone = 400, iron = 10 }, upkeep = 28, qualityBonus = 18 },
    carpentry = { name = "Mizarski atelje", cost = { gold = 3200, wood = 500, stone = 700, silver = 40, leather = 10 }, upkeep = 65, qualityBonus = 30 },
    royal_ram_atelier = { name = "Kraljevski atelje ovnov", cost = { gold = 13000, wood = 1200, stone = 1500, gold = 200, jewel = 25 }, upkeep = 280, qualityBonus = 55, prestigeBonus = 50 },
}
BatteringRamMaker.woodStock = 26; BatteringRamMaker.ironStock = 14; BatteringRamMaker.steelStock = 10; BatteringRamMaker.leatherStock = 12; BatteringRamMaker.ropeStock = 10; BatteringRamMaker.silverStock = 8; BatteringRamMaker.goldStock = 6; BatteringRamMaker.jewelStock = 6
BatteringRamMaker.productStock = {}; BatteringRamMaker.buildings = {}; BatteringRamMaker.maker = nil; BatteringRamMaker.activeMaking = {}; BatteringRamMaker.totalProducts = 0; BatteringRamMaker.dayTimer = 0
function BatteringRamMaker.init() BatteringRamMaker.woodStock=26; BatteringRamMaker.ironStock=14; BatteringRamMaker.steelStock=10; BatteringRamMaker.leatherStock=12; BatteringRamMaker.ropeStock=10; BatteringRamMaker.silverStock=8; BatteringRamMaker.goldStock=6; BatteringRamMaker.jewelStock=6; BatteringRamMaker.productStock={}; BatteringRamMaker.buildings={}; BatteringRamMaker.maker=nil; BatteringRamMaker.activeMaking={}; BatteringRamMaker.totalProducts=0; BatteringRamMaker.dayTimer=0; print("[BatteringRamMaker] Royal Battering Ram Maker System initialized (6 products, 4 buildings)") end
function BatteringRamMaker.hireMaker(n,s) s=s or math.random(55,95); local c=680+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BatteringRamMaker.maker={name=n or ("Ovnar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ovnar najet: %s (spretnost: %d)",BatteringRamMaker.maker.name,s),"success") end; return true end
function BatteringRamMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BatteringRamMaker.build(id) local ok,e=BatteringRamMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BatteringRamMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BatteringRamMaker.getQualityBonus() local b=0; for _,bd in ipairs(BatteringRamMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BatteringRamMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and BatteringRamMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and BatteringRamMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and BatteringRamMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.leatherCost and BatteringRamMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.ropeCost and BatteringRamMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and BatteringRamMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BatteringRamMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BatteringRamMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #BatteringRamMaker.buildings==0 then return false,"Potrebna delavnica" end; if not BatteringRamMaker.maker then return false,"Potreben ovnar" end; return true end
function BatteringRamMaker.make(pt,qty) qty=qty or 1; local ok,e=BatteringRamMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then BatteringRamMaker.woodStock=BatteringRamMaker.woodStock-d.woodCost*qty end; if d.ironCost then BatteringRamMaker.ironStock=BatteringRamMaker.ironStock-d.ironCost*qty end; if d.steelCost then BatteringRamMaker.steelStock=BatteringRamMaker.steelStock-d.steelCost*qty end; if d.leatherCost then BatteringRamMaker.leatherStock=BatteringRamMaker.leatherStock-d.leatherCost*qty end; if d.ropeCost then BatteringRamMaker.ropeStock=BatteringRamMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then BatteringRamMaker.silverStock=BatteringRamMaker.silverStock-d.silverCost*qty end; if d.goldCost then BatteringRamMaker.goldStock=BatteringRamMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BatteringRamMaker.jewelStock=BatteringRamMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if BatteringRamMaker.maker then t=math.max(1,t-math.floor(BatteringRamMaker.maker.skill/12)) end; table.insert(BatteringRamMaker.activeMaking,{id="ram_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BatteringRamMaker.completeMaking(m) local q=1.0+(BatteringRamMaker.getQualityBonus()/100); if BatteringRamMaker.maker then q=q+(BatteringRamMaker.maker.skill/150) end; q=math.min(2.5,q); BatteringRamMaker.productStock[m.productType]=(BatteringRamMaker.productStock[m.productType] or 0)+m.quantity; BatteringRamMaker.totalProducts=BatteringRamMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BatteringRamMaker.maker then BatteringRamMaker.maker.itemsMade=BatteringRamMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BatteringRamMaker.maker.skill=math.min(100,BatteringRamMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ovn izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"batteringram.completed",{productName=m.productName,attack=m.attack,durability=m.durability}) end end
function BatteringRamMaker.update(dt) if not _G.state then return end; BatteringRamMaker.dayTimer=BatteringRamMaker.dayTimer+dt; if BatteringRamMaker.dayTimer>=30 then BatteringRamMaker.dayTimer=0; for i=#BatteringRamMaker.activeMaking,1,-1 do local m=BatteringRamMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BatteringRamMaker.completeMaking(m); table.remove(BatteringRamMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BatteringRamMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BatteringRamMaker.maker then tu=tu+25 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BatteringRamMaker.getStats() return {woodStock=BatteringRamMaker.woodStock,ironStock=BatteringRamMaker.ironStock,steelStock=BatteringRamMaker.steelStock,leatherStock=BatteringRamMaker.leatherStock,ropeStock=BatteringRamMaker.ropeStock,silverStock=BatteringRamMaker.silverStock,goldStock=BatteringRamMaker.goldStock,jewelStock=BatteringRamMaker.jewelStock,productStock=BatteringRamMaker.productStock,numBuildings=#BatteringRamMaker.buildings,hasMaker=BatteringRamMaker.maker~=nil,makerName=BatteringRamMaker.maker and BatteringRamMaker.maker.name or "—",makerSkill=BatteringRamMaker.maker and BatteringRamMaker.maker.skill or 0,activeMaking=#BatteringRamMaker.activeMaking,totalProducts=BatteringRamMaker.totalProducts} end
return BatteringRamMaker
